#!/usr/bin/env node
"use strict";

// Catalyst packages each function directory on its own, so code shared between functions
// has to be copied in. The root folders (shared/, shared-auth/, workspace2-proposal/,
// templates/, frontend-shared/) are the only place to edit; the copies inside functions/ and
// slate/ are generated by this script and are git-ignored. Slate's 404.html is kept identical
// to index.html so path-style links (/<slug>) reach the same router.
//
//   node scripts/sync-shared.js           regenerate every copy (run before `catalyst deploy`)
//   node scripts/sync-shared.js --check   exit 1 if any copy is missing or stale

const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const W2 = "workspace2-proposal";

const W2_BASE = [`${W2}/utils/errors`, `${W2}/utils/logging`, `${W2}/utils/cors`];
const w2 = (list) => list.map((src) => [src, src.replace(W2, "shared")]);
const AUTH = [["shared-auth", "shared-auth"]];

const MANIFEST = {
	"app-auth": [...AUTH],
	"workdrive-auth": [...AUTH],
	"spikra_document_upload": [...AUTH],
	"spikra_document_process": [...AUTH],
	"spikra_experience_deploy": [...AUTH],
	"spikra_process_status": [...AUTH],
	"spikra_experience_list": [...AUTH],
	"proposal-discovery": [...AUTH, ...w2(W2_BASE)],
	"proposal-api": [
		...AUTH,
		...w2([...W2_BASE, `${W2}/utils/validation`, `${W2}/services/proposal`, `${W2}/services/document-render`])
	],
	"proposal-processor": [
		...AUTH,
		...w2([
			...W2_BASE,
			`${W2}/utils/validation`,
			`${W2}/services/document-processing`,
			`${W2}/services/zia`,
			`${W2}/services/proposal`,
			`${W2}/services/document-render`
		])
	],
	"spikra_ai_analysis_v2": [...AUTH, ["shared/agent", "shared/agent"], ["shared/datastore", "shared/datastore"], ["shared/utils", "shared/utils"]],
	"spikra_experience_generate": [
		...AUTH,
		["shared/datastore", "shared/datastore"],
		["shared/utils", "shared/utils"],
		["templates/iSteel_Proposal_Site.html", "template.html"]
	]
};

const SLATE_APPS = ["spikra-experience", "spikra-w2-proposal"];

function listFiles(target) {
	if (!fs.existsSync(target)) return [];
	if (fs.statSync(target).isFile()) return [""];
	const out = [];
	const walk = (dir, rel) => {
		for (const name of fs.readdirSync(dir).sort()) {
			const full = path.join(dir, name);
			const next = path.join(rel, name);
			fs.statSync(full).isDirectory() ? walk(full, next) : out.push(next);
		}
	};
	walk(target, "");
	return out;
}

function isStale(src, dest) {
	const srcFiles = listFiles(src);
	const destFiles = listFiles(dest);
	if (srcFiles.join("|") !== destFiles.join("|")) return true;
	return srcFiles.some((rel) => !fs.readFileSync(path.join(src, rel)).equals(fs.readFileSync(path.join(dest, rel))));
}

const check = process.argv.includes("--check");
let stale = 0;

for (const [fn, entries] of Object.entries(MANIFEST)) {
	const fnDir = path.join(ROOT, "functions", fn);
	if (!check) {
		for (const top of new Set(entries.map(([, dest]) => dest.split("/")[0]).filter((d) => d.startsWith("shared")))) {
			fs.rmSync(path.join(fnDir, top), { recursive: true, force: true });
		}
	}
	for (const [srcRel, destRel] of entries) {
		const src = path.join(ROOT, srcRel);
		const dest = path.join(fnDir, destRel);
		if (!fs.existsSync(src)) {
			console.error(`missing source: ${srcRel}`);
			process.exit(1);
		}
		if (check) {
			if (isStale(src, dest)) {
				stale += 1;
				console.error(`stale: functions/${fn}/${destRel}`);
			}
		} else {
			fs.mkdirSync(path.dirname(dest), { recursive: true });
			fs.cpSync(src, dest, { recursive: true });
		}
	}
}

for (const app of SLATE_APPS) {
	const appDir = path.join(ROOT, "slate", app);
	const sharedDest = path.join(appDir, "assets", "shared");
	const sharedSrc = path.join(ROOT, "frontend-shared");
	if (check) {
		if (isStale(sharedSrc, sharedDest)) { stale += 1; console.error(`stale: slate/${app}/assets/shared`); }
		if (isStale(path.join(appDir, "index.html"), path.join(appDir, "404.html"))) { stale += 1; console.error(`stale: slate/${app}/404.html`); }
	} else {
		fs.rmSync(sharedDest, { recursive: true, force: true });
		fs.mkdirSync(path.dirname(sharedDest), { recursive: true });
		fs.cpSync(sharedSrc, sharedDest, { recursive: true });
		fs.copyFileSync(path.join(appDir, "index.html"), path.join(appDir, "404.html"));
	}
}

if (check) {
	if (stale) {
		console.error(`${stale} shared copies are out of date. Run: npm run sync:shared`);
		process.exit(1);
	}
	console.log("All shared copies are up to date.");
} else {
	console.log("Shared code synced into functions/.");
}
